use agent_runtime_protocol::domain::ports::{Transport, TransportError};
use agent_runtime_protocol::domain::schema::v0::{ToRuntimeMessage, ToServerMessage};
use agent_session::domain::model::AgentSessionId;

pub trait LiveAgentSession {
    fn id(&self) -> &AgentSessionId;
    async fn send(&self, message: ToRuntimeMessage) -> Result<(), TransportError>;
    async fn receive(&self) -> Result<Option<ToServerMessage>, TransportError>;
}

pub struct AgentSessionImpl<C> {
    id: AgentSessionId,
    connection: C,
}

impl<C> AgentSessionImpl<C> {
    pub fn new(id: AgentSessionId, connection: C) -> Self {
        Self { id, connection }
    }

    pub(crate) fn connection(&self) -> &C {
        &self.connection
    }
}

impl<C> LiveAgentSession for AgentSessionImpl<C>
where
    C: Transport<ToRuntimeMessage, ToServerMessage>,
{
    fn id(&self) -> &AgentSessionId {
        &self.id
    }

    async fn send(&self, message: ToRuntimeMessage) -> Result<(), TransportError> {
        self.connection.send(message).await
    }

    async fn receive(&self) -> Result<Option<ToServerMessage>, TransportError> {
        self.connection.recv().await
    }
}

