use std::collections::HashMap;

use agent_session::domain::model::AgentSessionId;

use super::LiveAgentSession;

pub trait AgentSessionManager<T>
where
    T: LiveAgentSession,
{
    fn create_session(&mut self, id: &AgentSessionId) -> &T;
    fn from_id(&self, id: &AgentSessionId) -> Option<&T>;
}

pub struct AgentSessionManagerImpl<T, F>
where
    T: LiveAgentSession,
    F: Fn(&AgentSessionId) -> T,
{
    sessions: HashMap<AgentSessionId, T>,
    session_factory: F,
}

impl<T, F> AgentSessionManagerImpl<T, F>
where
    T: LiveAgentSession,
    F: Fn(&AgentSessionId) -> T,
{
    pub fn new(session_factory: F) -> Self {
        Self {
            sessions: HashMap::new(),
            session_factory,
        }
    }
}

impl<T, F> AgentSessionManager<T> for AgentSessionManagerImpl<T, F>
where
    T: LiveAgentSession,
    F: Fn(&AgentSessionId) -> T,
{
    fn create_session(&mut self, id: &AgentSessionId) -> &T {
        self.sessions
            .entry(*id)
            .or_insert_with(|| (self.session_factory)(id))
    }

    fn from_id(&self, id: &AgentSessionId) -> Option<&T> {
        self.sessions.get(id)
    }
}

