use agent_client_protocol::RawJsonRpcMessage;
use agent_runtime_protocol::domain::schema::v0::{
    AcpMessage, SystemEvent, ToRuntimeMessage, ToServerMessage,
};
use agent_session::domain::model::AgentSessionId;
use serde_json::json;

use super::*;
use crate::testing::mocks::container::ContainerMock;

#[tokio::test]
async fn managed_session_speaks_to_its_container() {
    let session_id = AgentSessionId::TEST_A;
    let from_container = ToServerMessage::Event {
        event: SystemEvent::Unknown("agent/ready".to_owned()),
    };
    let expected_from_container = serde_json::to_value(&from_container).unwrap();

    let mut manager = AgentSessionManagerImpl::new(|id: &AgentSessionId| {
        AgentSessionImpl::new(*id, ContainerMock::new(*id, [from_container.clone()]))
    });
    let session = manager.create_session(&session_id);

    let to_container = ToRuntimeMessage::Acp(AcpMessage(
        RawJsonRpcMessage::notification(
            "session/prompt".to_owned(),
            json!({ "prompt": "hello" }),
        )
        .unwrap(),
    ));
    session.send(to_container.clone()).await.unwrap();

    let sent = session.connection().sent_messages();
    assert_eq!(sent.len(), 1);
    assert_eq!(
        serde_json::to_value(&sent[0]).unwrap(),
        serde_json::to_value(&to_container).unwrap()
    );
    assert_eq!(
        serde_json::to_value(session.receive().await.unwrap().unwrap()).unwrap(),
        expected_from_container
    );
    assert_eq!(manager.from_id(&session_id).unwrap().id(), &session_id);
}

