//! In-memory container test double.

use std::collections::VecDeque;
use std::sync::Mutex;

use agent_runtime_protocol::domain::ports::{Transport, TransportError};
use agent_runtime_protocol::domain::schema::v0::{ToRuntimeMessage, ToServerMessage};
use agent_session::domain::model::AgentSessionId;

use crate::domain::containers::Container;

/// A container connection backed by in-memory message queues.
pub struct ContainerMock {
    id: AgentSessionId,
    inbound: Mutex<VecDeque<ToServerMessage>>,
    outbound: Mutex<Vec<ToRuntimeMessage>>,
}

impl ContainerMock {
    /// Creates a mock with messages ready to be received by the session.
    pub fn new(id: AgentSessionId, inbound: impl IntoIterator<Item = ToServerMessage>) -> Self {
        Self {
            id,
            inbound: Mutex::new(inbound.into_iter().collect()),
            outbound: Mutex::new(Vec::new()),
        }
    }

    /// Returns a snapshot of the messages sent to the container.
    pub fn sent_messages(&self) -> Vec<ToRuntimeMessage> {
        self.outbound
            .lock()
            .expect("container mock outbound lock should not be poisoned")
            .clone()
    }
}

impl Transport<ToRuntimeMessage, ToServerMessage> for ContainerMock {
    async fn send(&self, message: ToRuntimeMessage) -> Result<(), TransportError> {
        self.outbound
            .lock()
            .expect("container mock outbound lock should not be poisoned")
            .push(message);
        Ok(())
    }

    async fn recv(&self) -> Result<Option<ToServerMessage>, TransportError> {
        Ok(self
            .inbound
            .lock()
            .expect("container mock inbound lock should not be poisoned")
            .pop_front())
    }
}

impl Container for ContainerMock {
    fn id(&self) -> AgentSessionId {
        self.id
    }
}

