use agent_runtime_protocol::domain::schema::v0::{SystemEvent, ToRuntimeMessage, ToServerMessage};
use bots::domain::models::BotId;
use chrono::{DateTime, Utc};
use macro_user_id::user_id::MacroUserIdStr;
use macro_uuid::Uuid;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct AgentSessionId(Uuid);

impl AgentSessionId {
    /// Wrap an existing UUID as an agent session id.
    pub fn new_from_uuid(id: Uuid) -> Self {
        Self(id)
    }

    /// The underlying UUID.
    pub fn as_uuid(&self) -> Uuid {
        self.0
    }

    #[cfg(test)]
    pub const TEST_A: Self = Self(Uuid::from_u128(0));
    #[cfg(test)]
    pub const TEST_B: Self = Self(Uuid::from_u128(1));
}

#[derive(Debug, Clone, Default)]
pub enum SessionStatus {
    /// No status updates received
    #[default]
    NoMessages,
    /// EventRecieved from container
    Event(SystemEvent),
    /// A session disconnected without sending a clsoed event
    Disconnected,
}

/// What a caller supplies to open a session.
///
/// Neither the session id nor the thread id are here: [`AgentSessionRepo::create`]
/// mints both. The thread in particular is the session's *own* thread, created
/// with the session rather than handed to it - a caller that had to invent one
/// would be guessing at an identity the session defines.
///
/// [`AgentSessionRepo::create`]: crate::domain::ports::AgentSessionRepo::create
#[derive(Debug, Clone)]
pub struct NewAgentSession {
    /// The thread the mention that opened this session was posted in, when it
    /// came from one.
    pub created_from_thread_id: Option<Uuid>,
    /// the bot id of the bot running the agent
    pub bot_id: BotId,
    /// model slug - TODO: probably a better type here
    pub model: String,
    /// harness slug - TODO: probably a better type here
    pub harness: String,
    /// repo we are working with
    pub repo_url: String,
}

/// A running or historical agent coding session.
#[derive(Debug, Clone)]
pub struct AgentSession {
    /// id of the agent session
    pub id: AgentSessionId,
    /// if this was created by `@` in a thread
    pub created_from_thread_id: Option<Uuid>,
    /// the thread id of the comms thread
    pub thread_id: Uuid,
    /// the bot id of the bot running the agent
    pub bot_id: BotId,
    /// model slug - TODO: probably a better type here
    pub model: String,
    /// harness slug - TODO: probably a better type here
    pub harness: String,
    /// repo we are working with
    pub repo_url: String,
    /// ACP session if we have one
    pub acp_session_id: Option<String>,
    pub status: SessionStatus,
    pub created_at: DateTime<Utc>,
    pub modified_at: DateTime<Utc>,
}

#[derive(Debug, Clone)]
pub enum Message {
    ToServer(ToServerMessage),
    ToRuntime(ToRuntimeMessage),
}

/// What the thread lookup found for an incoming channel message.
///
/// A session is scoped to one bot in one thread, and a message can relate to it
/// two different ways: posted in the thread the session was *created from*, or
/// posted inside the session's own thread. Callers act differently on each, so
/// one query answers all three cases rather than making them ask twice.
#[derive(Debug, Clone)]
pub enum ThreadSession {
    /// No session for this bot in this thread.
    None,
    /// The bot's session, created from the thread the message is in.
    CreatedFromThisThread(AgentSession),
    /// The message arrived inside the session's own thread.
    InSessionThread(AgentSession),
}

#[derive(Debug, Clone)]
pub struct AgentSessionLog {
    pub agent_session_id: AgentSessionId,
    /// if this is ACP sent by a user this will be Some
    pub user_id: Option<MacroUserIdStr<'static>>,
    pub content: Message,
}

use bots::domain::models::BotId;
use macro_uuid::Uuid;

use super::error::Result;
use super::model::*;

/// `Send + Sync + 'static` and `Send` futures because callers drive sessions
/// from spawned tasks - a Kafka consumer hands each message to its own task, and
/// a repo whose futures are not `Send` cannot be used there.
pub trait AgentSessionRepo: Send + Sync + 'static {
    /// Open a session, minting its id and its own thread.
    ///
    /// Returns the whole session rather than just the id: the caller needs the
    /// minted `thread_id` immediately - it is what a reply links to - and
    /// re-reading the row to learn a value this call just generated would be
    /// silly.
    fn create(&self, session: NewAgentSession)
    -> impl Future<Output = Result<AgentSession>> + Send;

    /// Get an agent session by id.
    fn get(&self, id: AgentSessionId) -> impl Future<Output = Result<AgentSession>> + Send;

    /// Resolve what `bot`'s session state is for the thread a channel message
    /// arrived in.
    ///
    /// One query rather than two lookups: the caller needs to know whether the
    /// message came from the thread that started the session or from inside the
    /// session's own thread, and those are different columns.
    fn find_for_thread(
        &self,
        bot: BotId,
        thread_id: Uuid,
    ) -> impl Future<Output = Result<ThreadSession>> + Send;

    /// Update an existing agent session.
    fn update(&self, session: AgentSession) -> impl Future<Output = Result<()>> + Send;

    /// Delete an agent session by id.
    fn delete(&self, id: AgentSessionId) -> impl Future<Output = Result<()>> + Send;
}

pub trait AgentSessionLogRepo: Send + Sync + 'static {
