138	                let service = Arc::clone(&self.service);
139	                tokio::spawn(async move {
140	                    let _ = service
141	                        .handle_agent_connected(session_id)
142	                        .await
143	                        .inspect_err(
144	                            |e| tracing::error!(error=?e, %session_id, "failed to start ACP session"),
145	                        );
146	                });
147	            }
148	
149	            let _ = self
150	                .service
151	                .handle_system_event(session_id, event)
152	                .await
153	                .inspect_err(|e| tracing::error!(error=?e, %session_id, "system event failed"));
154	        }
155	        acp_task.abort();
156	
157	        // `connection` is kept alive for the whole connection's lifetime -
158	        // dropping it earlier would stop its driver task and close both
159	        // channels out from under the loops above.
160	        drop(connection);
161	
162	        if self.attachments.unregister(session_id, registration) {
163	            self.service.handle_agent_detached(session_id);
164	        }
165	        tracing::info!(%session_id, epoch, "agent runtime disconnected");
166	    }
167	}
