118	async fn run_server<H>(
119	    mut inbound: tokio::sync::mpsc::UnboundedReceiver<ToServerMessage>,
120	    outbound: UnboundedSender<ToRuntimeMessage>,
121	    system_events: H,
122	    mut acp: AcpChannel,
123	) where
124	    H: SystemEventHandler,
125	{
126	    // Whether the caller's ACP channel is still open. A caller that only
127	    // wants events is free to drop its ACP channel immediately; that must
128	    // not tear down event handling, so once the ACP side closes we simply
129	    // stop selecting on it instead of breaking the loop.
130	    let mut acp_open = true;
131	    loop {
132	        tokio::select! {
133	            message = inbound.recv() => {
134	                let Some(message) = message else {
135	                    break;
136	                };
137	                match message {
138	                    ToServerMessage::Event { event } => {
139	                        system_events.handle(event).await;
140	                    }
141	                    ToServerMessage::Acp(AcpMessage(raw)) => {
142	                        if acp_open && acp.tx.unbounded_send(Ok(raw)).is_err() {
143	                            acp_open = false;
144	                        }
145	                    }
146	                }
147	            }
148	            message = acp.rx.next(), if acp_open => {
149	                match message {
150	                    Some(Ok(raw)) => {
151	                        if outbound.send(ToRuntimeMessage::Acp(AcpMessage(raw))).is_err() {
152	                            break;
153	                        }
154	                    }
155	                    _ => acp_open = false,
156	                }
157	            }
158	        }
159	    }
160	}
