165	    mut acp: AcpChannel,
166	) {
167	    // See the matching comment in `run_server`: dropping the ACP channel must
168	    // not tear down this connection - only an actual transport failure does.
169	    let mut acp_open = true;
170	    loop {
171	        tokio::select! {
172	            message = inbound.recv() => {
173	                let Some(message) = message else {
174	                    break;
175	                };
