1	//! Kafka consumer: every channel message, filtered down to the ones that
2	//! mention us.
3	//!
4	//! Scaffolding only - every operation is `todo!()`.
5	//!
6	//! The trigger is not an API call. The harness subscribes to `macro.channels`
7	//! and watches every message posted in every channel, so the filter in
8	//! [`crate::domain::mentions`] runs before anything expensive happens. A bad
9	//! predicate here spawns a Daytona sandbox and an agent_proxy chat for the
10	//! entire firehose, which is why the mention check is domain logic with its own
11	//! tests rather than an `if` in the poll loop.
12	//!
13	//! `ChannelMessagePostedMetadata` already carries `mentions`, `content`,
14	//! `thread_id`, and `sender`, so recognising a mention needs no database
15	//! lookup and no second subscription to `macro.mentions`.
16	//!
17	//! Offsets: the group starts at the newest offset, so the harness only ever
18	//! sees messages posted after it comes up. Starting at `earliest` would answer
19	//! every historical mention of the bot id - one sandbox and one chat per hit.
20	//!
21	//! Delivery is at-least-once, and both side effects (a sandbox, a chat) are
22	//! expensive and user-visible, so the worker must dedupe on
23	//! [`BotMention::message_id`] before acting. Redis is already a dependency;
24	//! `crates/task_dedup` exists if that proves too thin.
25	//!
26	//! `services/search_processing_service/src/inbound/kafka_consumer.rs` is the
27	//! reference for the parts this skeleton leaves out: bounded sequential
28	//! handoff, commit-after-handoff, committing malformed records so they cannot
29	//! wedge a partition, and bounded in-process retries.
30	
31	use std::sync::Arc;
32	use std::time::Duration;
33	
34	use agent_session::domain::ports::AgentSessionRepo;
35	use channels::domain::broker_events::{ChannelMacroEvent, ChannelTopicEvent};
36	use channels::domain::side_effects::ChannelBotTrigger;
37	use kafka_util::{GroupName, KafkaEventConsumer};
38	use macro_event_broker::{
39	    KafkaConsumerAdapter, MacroEvent, MacroEventCollection, MacroEventConsumerService, MessageParts,
40	};
41	use rootcause::prelude::ResultExt as _;
42	
43	use crate::domain::handler::MentionHandler;
44	use crate::domain::ports::{ChannelReplier, RuntimeAttachments, SandboxProvider};
45	
46	/// Consumer group owning this harness's channel-message offsets.
47	pub struct AgentHarnessConsumerGroup;
48	
49	impl GroupName for AgentHarnessConsumerGroup {
50	    const GROUP_NAME: &'static str = "agent-harness";
51	}
52	
53	macro_event_broker::declare_topics!(
54	    HarnessMacroEvent:
55	        ChannelMacroEvent,
56	);
57	
58	/// The grouped Kafka adapter this harness polls through.
59	pub type HarnessKafkaAdapter = KafkaConsumerAdapter<AgentHarnessConsumerGroup, HarnessMacroEvent>;
60	
61	/// The typed consumer the poll loop receives from.
62	pub type HarnessKafkaConsumer = MacroEventConsumerService<HarnessMacroEvent, HarnessKafkaAdapter>;
63	
64	/// How long to wait before polling again after a receive error, so a broker
65	/// outage does not spin.
66	const RECEIVE_ERROR_RETRY_DELAY: Duration = Duration::from_secs(1);
67	
68	/// Build the consumer: join the group and subscribe to every declared topic.
69	///
70	/// Offsets follow the group, so the very first run of a new group starts at the
71	/// newest offset and later runs resume from the last commit.
72	pub fn consumer(brokers: &str) -> Result<HarnessKafkaConsumer, rootcause::Report> {
73	    let consumer = KafkaEventConsumer::<AgentHarnessConsumerGroup>::from_env(brokers)?;
74	    let consumer = KafkaConsumerAdapter::<AgentHarnessConsumerGroup, ()>::new(consumer)
75	        .subscribe::<HarnessMacroEvent>()
76	        .context("failed to subscribe to agent harness event topics")?;
77	    Ok(MacroEventConsumerService::new(consumer))
78	}
79	
80	/// Poll `macro.channels` forever, logging every message.
81	///
82	/// The handler is threaded through but deliberately not called yet:
83	/// [`crate::domain::mentions::mentions_harness`] is still `todo!()`, so
84	/// filtering would panic on the first message. Until it lands this proves the
85	/// group joins, the topic is subscribed, and payloads decode.
86	///
87	/// It does not commit offsets either - so a restart re-reads whatever was
88	/// uncommitted, which for a log-only loop is what you want.
89	pub async fn run<Provider, Attach, Sessions, Replier>(
90	    _handler: Arc<MentionHandler<Provider, Attach, Sessions, Replier>>,
91	    consumer: HarnessKafkaConsumer,
92	) -> anyhow::Result<()>
93	where
94	    Provider: SandboxProvider,
95	    Attach: RuntimeAttachments,
96	    Sessions: AgentSessionRepo,
97	    Replier: ChannelReplier,
98	{
99	    tracing::info!(
100	        topics = ?HarnessMacroEvent::topics(),
101	        group = AgentHarnessConsumerGroup::GROUP_NAME,
102	        "agent harness listening for channel events"
103	    );
104	
105	    loop {
106	        let message = match consumer.recv().await {
107	            Ok(message) => message,
108	            Err(error) => {
109	                tracing::error!(error = ?error, "kafka receive failed");
110	                tokio::time::sleep(RECEIVE_ERROR_RETRY_DELAY).await;
111	                continue;
112	            }
113	        };
114	
115	        let topic = message.inner().topic().to_owned();
116	        let key = message.inner().key().map(str::to_owned);
117	
118	        match message.decode_payload() {
119	            Ok(HarnessMacroEvent::ChannelMacroEvent(event)) => {
120	                log_channel_event(&topic, key.as_deref(), &event);
121	            }
122	            Err(error) => {
123	                tracing::warn!(
124	                    %topic,
125	                    ?key,
126	                    error = ?error,
127	                    "undecodable record; skipping"
128	                );
129	            }
130	        }
131	    }
132	}
133	
134	/// Log one decoded channel event, naming the variant so the interesting ones
135	/// stand out from channel lifecycle noise.
136	fn log_channel_event(topic: &str, key: Option<&str>, event: &ChannelMacroEvent) {
137	    let envelope = event.event();
138	    let variant = match &envelope.event {
139	        ChannelTopicEvent::Created(_) => "channel.created",
140	        ChannelTopicEvent::Updated(_) => "channel.updated",
141	        ChannelTopicEvent::Deleted(_) => "channel.deleted",
142	        ChannelTopicEvent::MessagePosted(_) => "channel.message_posted",
143	        ChannelTopicEvent::MessagePatched(_) => "channel.message_patched",
144	        ChannelTopicEvent::MessageDeleted(_) => "channel.message_deleted",
145	        ChannelTopicEvent::MessageAttachmentCreated(_) => "channel.message_attachment_created",
146	        ChannelTopicEvent::MessageAttachmentRemoved(_) => "channel.message_attachment_removed",
147	        ChannelTopicEvent::ParticipantAdded(_) => "channel.participant_added",
148	        ChannelTopicEvent::ParticipantRemoved(_) => "channel.participant_removed",
149	    };
150	
151	    // Message bodies and mentions are the whole point of the smoke test, so a
152	    // posted message gets its own line with the fields the handler will read.
153	    if let ChannelTopicEvent::MessagePosted(posted) = &envelope.event {
154	        tracing::info!(
155	            %topic,
156	            ?key,
157	            event = variant,
158	            channel_id = %posted.channel_id,
159	            message_id = %posted.message_id,
160	            thread_id = ?posted.thread_id,
161	            mentions = ?posted.mentions,
162	            content = %posted.content,
163	            "message posted"
164	        );
165	        return;
166	    }
167	
168	    tracing::info!(%topic, ?key, event = variant, "channel event");
169	}
