/// Resume: a stored acp_session_id means load, not new.
#[tokio::test]
async fn resuming_loads_the_stored_acp_session() {
    let container = ContainerMock::new(id);
    let agent = container.agent();
    let stored = Some(AcpId::new("acp-abc"));
    let session = AgentSessionImpl::new(id, container.clone(), LogRepoMock::new(), stored);

    container.sends_ready();
    session.step().await.unwrap();
    agent.sends_reply(req(1), json!({ "protocolVersion": 1 }));
    session.step().await.unwrap();

    assert_eq!(agent.received_methods(), ["initialize", "session/load"]);
}

/// A container that repeats itself must not start two handshakes.
#[tokio::test]
async fn a_second_ready_event_is_ignored() {
    // ... container.sends_ready(); step; container.sends_ready(); step;
    assert_eq!(agent.received_methods(), ["initialize"]);
}

/// Everything queued before the handshake drains in the order it arrived.
#[tokio::test]
async fn pending_prompts_flush_in_order() {
    session.send_message(Some(user()), prompt("first")).await.unwrap();
    session.send_message(Some(user()), prompt("second")).await.unwrap();

    container.sends_ready();
    session.step().await.unwrap();
    agent.sends_reply(req(1), json!({ "protocolVersion": 1 })); session.step().await.unwrap();
    agent.sends_reply(req(2), json!({ "sessionId": "acp-abc" })); session.step().await.unwrap();

    let sent = agent.received_frames();
    assert_eq!(text_of(&sent[2]), "first");
    assert_eq!(text_of(&sent[3]), "second");
}

/// Agent-initiated traffic is logged even though nothing asked for it.
#[tokio::test]
async fn agent_notifications_are_logged() {
    // ... reach Live ...
    agent.sends_notification("session/update", json!({ "text": "thinking" }));
    session.step().await.unwrap();

    assert_eq!(log.summary().last().unwrap(), "<- session/update");
}

/// A handshake the agent refuses leaves the session unusable rather than silently idle.
#[tokio::test]
async fn a_failed_initialize_kills_the_session() {
    container.sends_ready();
    session.step().await.unwrap();
    agent.sends_error(req(1), -32603, "no agent");
    session.step().await.unwrap();

    assert!(matches!(session.state(), SessionState::Dead(_)));
    assert!(session.send_message(Some(user()), prompt("hello")).await.is_err());
}

/// A container that dies mid-handshake does not leave prompts pending forever.
#[tokio::test]
async fn disconnect_before_ready_fails_pending_sends() {
    session.send_message(Some(user()), prompt("fix it")).await.unwrap();
    container.disconnects();
    session.step().await.unwrap();

    assert!(matches!(session.state(), SessionState::Dead(_)));
    assert!(agent.received_methods().is_empty());
}
```

## One problem with the mock as it stands

`ContainerMock::recv()` currently returns `Ok(None)` when its queue is empty (`mocks/container.rs:47-53`), but `Transport`'s contract says `Ok(None)` means **the counterpart closed** (`ports.rs:26`). The mock conflates "nothing yet" with "gone."

That's survivable while a test hand-drives `step()`, but it breaks two things: `container.disconnects()` becomes indistinguishable from an idle queue, and the eventual real `pump()` would exit immediately on its first empty poll.

Fix is small — back the mock with a `tokio::sync::mpsc` channel so `recv()` genuinely awaits and closing is explicit:

```rust
pub struct ContainerMock {
    id: AgentSessionId,
    inbound_tx: UnboundedSender<ToServerMessage>,      // sends_*/disconnects write here
    inbound_rx: Arc<Mutex<UnboundedReceiver<ToServerMessage>>>,
    agent: FakeAgent,
}
```

`disconnects()` drops the sender; `recv()` returns `None` only then. That also means `pump()` gets testable for free later, and a test that forgets to enqueue hangs instead of silently seeing a closed stream — a hang is the better failure, since it points at the missing `sends_*` call.

Want me to start building? I'd do `ContainerMock` + `FakeAgent` + `LogRepoMock` first, then the happy-path test compiling-but-failing against a `todo!()` state machine, then fill it in.

