172	/// same value the in-process side-effect path produces.
173	///
174	/// `channels::domain::side_effects::bot_mention_ids` does the matching, so the
175	/// `bot|<uuid>` form and the user-tagged-bot quirk stay owned by `channels`
176	/// instead of being reimplemented here.
177	///
178	/// Returns `None` for anything that is not a posted message, which is most of
179	/// the topic.
180	#[expect(
181	    dead_code,
182	    reason = "wired up once the loop dispatches instead of logging"
183	)]
184	fn to_trigger(_event: &ChannelMacroEvent) -> Option<ChannelBotTrigger> {
185	    todo!("match MessagePosted, build MutatedMessage, bot_ids via bot_mention_ids")
186	}
