```rust
use super::*;

/// NewSession -> container boots -> prompt buffered -> ready -> handshake -> flush.
#[test]
fn buffers_a_prompt_until_the_handshake_completes() {
    // Fresh session: no stored acp_session_id, so the handshake mints one.
    let mut core = SessionCore::new(AgentSessionId::TEST_A, None);

    // A prompt arrives while the container is still booting. Nothing on the wire.
    let actions = core.on_send(Some(user()), prompt("fix the flaky test"));
    assert_eq!(actions, vec![]);
    assert!(matches!(core.state(), SessionState::Booting { .. }));

    // Container reports ready. AcpReady means "handshakeable", not "sendable":
    // initialize goes out, the prompt stays buffered.
    let actions = core.on_inbound(event(SystemEvent::AcpReady));
    assert_eq!(actions, vec![Action::Send(initialize(req(1)))]);
    assert!(matches!(core.state(), SessionState::Handshaking { .. }));

