use std::sync::{Arc, Mutex};

use agent_session::domain::error::Result;
use agent_session::domain::model::{AgentSessionId, AgentSessionLog};
use agent_session::domain::ports::AgentSessionLogRepo;

use crate::testing::helpers::transcript::TranscriptEntry;

/// The session log, kept in memory.
///
/// Satisfies the same port as `PgAgentSessionLogRepo`, so a session is wired
/// identically here and in production.
///
/// Cloning shares one log, so a test can keep a handle after moving it into a
/// session.
#[derive(Clone, Default)]
pub struct LogRepoMock {
    entries: Arc<Mutex<Vec<AgentSessionLog>>>,
}

impl LogRepoMock {
    /// Create an empty log.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Every entry appended, in order.
    #[must_use]
    pub fn entries(&self) -> Vec<AgentSessionLog> {
        self.lock().clone()
    }

    /// The log reduced to direction and frame kind, for assertions.
    #[must_use]
    pub fn transcript(&self) -> Vec<TranscriptEntry> {
        self.lock().iter().map(TranscriptEntry::of).collect()
    }

    fn lock(&self) -> std::sync::MutexGuard<'_, Vec<AgentSessionLog>> {
        self.entries
            .lock()
            .expect("log mock lock should not be poisoned")
    }
}

impl AgentSessionLogRepo for LogRepoMock {
    async fn create(&self, log: AgentSessionLog) -> Result<()> {
        self.lock().push(log);
        Ok(())
    }

    async fn list_by_session(&self, agent_session_id: AgentSessionId) -> Result<Vec<AgentSessionLog>> {
        Ok(self
            .lock()
            .iter()
            .filter(|entry| entry.agent_session_id == agent_session_id)
            .cloned()
            .collect())
    }
}

