use agent_client_protocol::RawJsonRpcMessage;
use agent_runtime_protocol::domain::schema::v0::{AcpMessage, SystemEvent, ToRuntimeMessage};
use agent_session::domain::model::AgentSessionId;
use serde_json::json;

