use crate::testing::helpers::container::ContainerMock;
use crate::testing::helpers::transcript::AcpMethod;

#[tokio::test]
async fn managed_session_speaks_to_its_container() {
    let session_id = AgentSessionId::TEST_A;
    let container = ContainerMock::new(session_id);
    let agent = container.agent();
    container.sends_event(SystemEvent::Unknown("agent/ready".to_owned()));

    let mut manager = AgentSessionManagerImpl::new({
        let container = container.clone();
        move |id: &AgentSessionId| AgentSessionImpl::new(*id, container.clone())
    });
    let session = manager.create_session(&session_id);

    let to_container = ToRuntimeMessage::Acp(AcpMessage(
        RawJsonRpcMessage::notification("session/prompt".to_owned(), json!({ "prompt": "hello" }))
            .unwrap(),
    ));
    session.send(to_container).await.unwrap();

    assert_eq!(agent.received_methods(), [AcpMethod::SessionPrompt]);
    assert!(matches!(
        session.receive().await.unwrap(),
        Some(ToServerMessage::Event { event }) if event == SystemEvent::Unknown("agent/ready".to_owned())
    ));
    assert_eq!(manager.from_id(&session_id).unwrap().id(), &session_id);
}

