//! A fake agent process, speaking only raw ACP.

use std::sync::{Arc, Mutex};

use agent_client_protocol::{Error as AcpError, RawJsonRpcMessage, RequestId};
use tokio::sync::mpsc::UnboundedSender;

use crate::testing::helpers::transcript::{AcpMethod, FrameKind};

/// The agent inside a container.
///
/// Like the real sidecar it knows nothing of the `agent-runtime.v0` envelope:
/// it reads and writes complete JSON-RPC values and nothing else. The
/// container it belongs to is what wraps those frames for the wire.
///
/// Cloning shares one agent, so a test can hold a handle after the container
/// it belongs to has been moved into a session.
#[derive(Clone)]
pub struct FakeAgent {
    /// `None` once the container has disconnected.
    to_harness: Arc<Mutex<Option<UnboundedSender<RawJsonRpcMessage>>>>,
    from_harness: Arc<Mutex<Vec<RawJsonRpcMessage>>>,
}

impl FakeAgent {
    pub(crate) fn new(to_harness: UnboundedSender<RawJsonRpcMessage>) -> Self {
        Self {
            to_harness: Arc::new(Mutex::new(Some(to_harness))),
            from_harness: Arc::new(Mutex::new(Vec::new())),
        }
    }

    /// Answer a request the harness sent.
    pub fn sends_reply(&self, id: RequestId, result: serde_json::Value) {
        self.send(RawJsonRpcMessage::response(id, Ok(result)));
    }

    /// Fail a request the harness sent.
    pub fn sends_error(&self, id: RequestId, error: AcpError) {
        self.send(RawJsonRpcMessage::response(id, Err(error)));
    }

    /// Volunteer a notification, as the agent does while working.
    pub fn sends_notification(&self, method: &str, params: serde_json::Value) {
        let frame = RawJsonRpcMessage::notification(method.to_owned(), params)
            .expect("notification params should be a JSON object or array");
        self.send(frame);
    }

    /// Every frame the harness has delivered, in order.
    #[must_use]
    pub fn received_frames(&self) -> Vec<RawJsonRpcMessage> {
        self.lock_received().clone()
    }

    /// What kind of frame the harness delivered, in order.
    #[must_use]
    pub fn received_kinds(&self) -> Vec<FrameKind> {
        self.lock_received().iter().map(FrameKind::of).collect()
    }

    /// The methods the harness invoked, in order. Responses have no method, so
    /// they are absent.
    #[must_use]
    pub fn received_methods(&self) -> Vec<AcpMethod> {
        self.received_kinds()
            .into_iter()
            .filter_map(|kind| match kind {
                FrameKind::Request { method, .. } | FrameKind::Notification { method } => {
                    Some(method)
                }
                FrameKind::Response { .. } | FrameKind::Event(_) => None,
            })
            .collect()
    }

    /// Record a frame the harness sent this agent.
    pub(crate) fn deliver(&self, frame: RawJsonRpcMessage) {
        self.lock_received().push(frame);
    }

    /// Stop being able to talk, so the harness sees the stream end.
    pub(crate) fn close(&self) {
        self.to_harness
            .lock()
            .expect("fake agent sender lock should not be poisoned")
            .take();
    }

    fn send(&self, frame: RawJsonRpcMessage) {
        if let Some(to_harness) = self
            .to_harness
            .lock()
            .expect("fake agent sender lock should not be poisoned")
            .as_ref()
        {
            let _ = to_harness.send(frame);
        }
    }

    fn lock_received(&self) -> std::sync::MutexGuard<'_, Vec<RawJsonRpcMessage>> {
        self.from_harness
            .lock()
            .expect("fake agent received lock should not be poisoned")
    }
}

