//! A typed projection of a session's log, for assertions.
//!
//! Comparing raw [`AgentSessionLog`] entries means diffing nested JSON-RPC
//! blobs. This reduces each entry to the direction it travelled and the kind of
//! frame it was, so a failing assertion names what actually differs.

use agent_client_protocol::{RawJsonRpcMessage, RequestId};
use agent_runtime_protocol::domain::schema::v0::{
    AcpMessage, SystemEvent, ToRuntimeMessage, ToServerMessage,
};
use agent_session::domain::model::{AgentSessionLog, Message};

/// Which way a frame crossed the wire.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Direction {
    /// Agent Service to Agent Runtime.
    ToRuntime,
    /// Agent Runtime to Agent Service.
    FromRuntime,
}

/// An ACP method, named where we care and preserved where we don't.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AcpMethod {
    /// `initialize`
    Initialize,
    /// `session/new`
    SessionNew,
    /// `session/load`
    SessionLoad,
    /// `session/prompt`
    SessionPrompt,
    /// `session/update`
    SessionUpdate,
    /// Any other method name.
    Other(String),
}

impl AcpMethod {
    /// Recognise a method name off the wire.
    #[must_use]
    pub fn from_wire(method: &str) -> Self {
        match method {
            "initialize" => Self::Initialize,
            "session/new" => Self::SessionNew,
            "session/load" => Self::SessionLoad,
            "session/prompt" => Self::SessionPrompt,
            "session/update" => Self::SessionUpdate,
            other => Self::Other(other.to_owned()),
        }
    }
}

/// What a logged frame was, shorn of its payload.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FrameKind {
    /// A runtime lifecycle event rather than ACP traffic.
    Event(SystemEvent),
    /// A JSON-RPC request.
    Request {
        /// Correlates the matching response.
        id: RequestId,
        /// The method invoked.
        method: AcpMethod,
    },
    /// A JSON-RPC response.
    Response {
        /// The request this answers.
        id: RequestId,
    },
    /// A JSON-RPC notification.
    Notification {
        /// The method notified.
        method: AcpMethod,
    },
}

impl FrameKind {
    /// Project one raw ACP frame.
    #[must_use]
    pub fn of(frame: &RawJsonRpcMessage) -> Self {
        match frame {
            RawJsonRpcMessage::Request(request) => Self::Request {
                id: request.id.clone(),
                method: AcpMethod::from_wire(&request.method),
            },
            RawJsonRpcMessage::Notification(notification) => Self::Notification {
                method: AcpMethod::from_wire(&notification.method),
            },
            RawJsonRpcMessage::Response(response) => Self::Response {
                id: frame
                    .response_id()
                    .cloned()
                    .unwrap_or_else(|| unreachable!("{response:?} is a response")),
            },
        }
    }
}

/// One logged frame: which way it went, and what it was.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TranscriptEntry {
    /// Which way it crossed the wire.
    pub direction: Direction,
    /// What kind of frame it was.
    pub frame: FrameKind,
}

impl TranscriptEntry {
    /// Project one log entry.
    #[must_use]
    pub fn of(log: &AgentSessionLog) -> Self {
        match &log.content {
            Message::ToServer(ToServerMessage::Event { event }) => {
                from_runtime(FrameKind::Event(event.clone()))
            }
            Message::ToServer(ToServerMessage::Acp(AcpMessage(frame))) => {
                from_runtime(FrameKind::of(frame))
            }
            Message::ToRuntime(ToRuntimeMessage::Acp(AcpMessage(frame))) => {
                to_runtime(FrameKind::of(frame))
            }
        }
    }
}

/// An entry the Agent Service sent to the runtime.
#[must_use]
pub fn to_runtime(frame: FrameKind) -> TranscriptEntry {
    TranscriptEntry {
        direction: Direction::ToRuntime,
        frame,
    }
}

/// An entry the runtime sent to the Agent Service.
#[must_use]
pub fn from_runtime(frame: FrameKind) -> TranscriptEntry {
    TranscriptEntry {
        direction: Direction::FromRuntime,
        frame,
    }
}

