#[tokio::test]
async fn managed_session_speaks_to_its_container() {
    let session_id = AgentSessionId::TEST_A;
    let container = ContainerMock::new(session_id);
    let agent = container.agent();
    container.sends_event(SystemEvent::Unknown("agent/ready".to_owned()));

    let mut manager = AgentSessionManagerImpl::new({
        let container = container.clone();
        move |id: &AgentSessionId| AgentSessionImpl::new(*id, container.clone())
    });
    let session = manager.create_session(&session_id);

