/// Which way a frame crossed the wire.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Direction {
    /// Agent Service to Agent Runtime.
    ToRuntime,
    /// Agent Runtime to Agent Service.
    FromRuntime,
}

/// An ACP method, named where we care and preserved where we don't.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AcpMethod {
    /// `initialize`
    Initialize,
    /// `session/new`
    SessionNew,
    /// `session/load`
    SessionLoad,
    /// `session/prompt`
    SessionPrompt,
    /// `session/update`
    SessionUpdate,
    /// Any other method name.
    Other(String),
}

impl AcpMethod {
    /// Recognise a method name off the wire.
    ///
    /// Every name is claimed by the ACP crate's own message types rather than
    /// spelled here, so a method this crate renames stops matching instead of
    /// silently disagreeing with a string literal.
    #[must_use]
    pub fn from_wire(method: &str) -> Self {
        if InitializeRequest::matches_method(method) {
            Self::Initialize
        } else if NewSessionRequest::matches_method(method) {
            Self::SessionNew
        } else if LoadSessionRequest::matches_method(method) {
            Self::SessionLoad
        } else if PromptRequest::matches_method(method) {
            Self::SessionPrompt
        } else if SessionNotification::matches_method(method) {
            Self::SessionUpdate
        } else {
            Self::Other(method.to_owned())
        }
    }
}

/// What a logged frame was, shorn of its payload.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FrameKind {
    /// A runtime lifecycle event rather than ACP traffic.
    Event(SystemEvent),
    /// A JSON-RPC request.
    Request {
        /// Correlates the matching response.
        id: RequestId,
        /// The method invoked.
        method: AcpMethod,
    },
    /// A JSON-RPC response.
    Response {
        /// The request this answers.
        id: RequestId,
    },
    /// A JSON-RPC notification.
    Notification {
        /// The method notified.
        method: AcpMethod,
    },
}

impl FrameKind {
    /// Project one raw ACP frame.
