        let container = container.clone();
        move |id: &AgentSessionId| AgentSessionImpl::new(*id, container.clone())
    });
    let session = manager.create_session(&session_id);

    let to_container = ToRuntimeMessage::Acp(AcpMessage(
        RawJsonRpcMessage::request(
            "session/prompt".to_owned(),
            json!({
                "sessionId": "acp-abc",
                "prompt": [{ "type": "text", "text": "hello" }],
