//! A typed projection of a session's log, for assertions.
//!
//! Comparing raw [`AgentSessionLog`] entries means diffing nested JSON-RPC
//! blobs. This parses each one into the ACP crate's own message enums, so an
//! assertion names real variants and direction is structural rather than a
//! field to read.
//!
//! Direction picks the enum: the same method name means different things by
//! role, so what the harness sends is a [`ClientRequest`] and what the agent
//! sends back is an [`AgentRequest`].

use agent_client_protocol::schema::v1::{
    AgentNotification, AgentRequest, ClientNotification, ClientRequest, RequestId,
};
use agent_client_protocol::{JsonRpcMessage, RawJsonRpcMessage};
use agent_runtime_protocol::domain::schema::v0::{
    AcpMessage, SystemEvent, ToRuntimeMessage, ToServerMessage,
};
use agent_session::domain::model::{AgentSessionLog, Message};

/// One logged frame, named from the harness's point of view.
///
/// Responses are the one lossy case: [`agent_client_protocol::schema::v1::AgentResponse`]
/// is keyed by method, so typing a response means correlating its id back to
/// the request that caused it. That correlation is the state machine's job and
/// the thing under test, so a helper that reimplemented it would be marking
/// its own homework.
#[derive(Debug, Clone)]
pub enum TranscriptEntry {
    /// A runtime lifecycle event.
    Event(SystemEvent),
    /// A request the harness sent the agent.
    Sent(ClientRequest),
    /// A notification the harness sent the agent.
    SentNotification(ClientNotification),
    /// The harness answering a request the agent made.
    SentResponse(RequestId),
    /// A request the agent sent the harness.
    Received(AgentRequest),
    /// A notification the agent sent the harness.
    ReceivedNotification(AgentNotification),
    /// The agent answering a request the harness made.
    ReceivedResponse(RequestId),
}

impl TranscriptEntry {
    /// Project one log entry.
    ///
    /// # Panics
    ///
    /// If a frame does not parse as ACP traffic, or the log holds a protocol
    /// variant this does not know about. Both mean the helper is out of date
    /// with the protocol, which should fail loudly rather than project wrong.
    #[must_use]
    pub fn of(log: &AgentSessionLog) -> Self {
        match &log.content {
            Message::ToServer(ToServerMessage::Event { event }) => Self::Event(event.clone()),
            Message::ToServer(ToServerMessage::Acp(AcpMessage(frame))) => from_agent(frame),
            Message::ToRuntime(ToRuntimeMessage::Acp(AcpMessage(frame))) => to_agent(frame),
            other => panic!("transcript helper does not handle {other:?}"),
        }
    }
}

/// Project a frame the harness sent the agent.
fn to_agent(frame: &RawJsonRpcMessage) -> TranscriptEntry {
    match frame {
        RawJsonRpcMessage::Request(request) => {
            TranscriptEntry::Sent(parse(&request.method, &request.params))
        }
        RawJsonRpcMessage::Notification(notification) => {
            TranscriptEntry::SentNotification(parse(&notification.method, &notification.params))
        }
        RawJsonRpcMessage::Response(_) => TranscriptEntry::SentResponse(response_id(frame)),
    }
}

/// Project a frame the agent sent the harness.
fn from_agent(frame: &RawJsonRpcMessage) -> TranscriptEntry {
    match frame {
        RawJsonRpcMessage::Request(request) => {
            TranscriptEntry::Received(parse(&request.method, &request.params))
        }
        RawJsonRpcMessage::Notification(notification) => {
            TranscriptEntry::ReceivedNotification(parse(&notification.method, &notification.params))
        }
        RawJsonRpcMessage::Response(_) => TranscriptEntry::ReceivedResponse(response_id(frame)),
    }
}

/// Parse a frame into whichever ACP message enum the caller asked for.
pub(crate) fn parse<T>(method: &str, params: &impl serde::Serialize) -> T
where
    T: JsonRpcMessage,
{
    T::parse_message(method, params)
        .unwrap_or_else(|error| panic!("{method} did not parse as ACP: {error}"))
}

fn response_id(frame: &RawJsonRpcMessage) -> RequestId {
    frame.response_id().cloned().expect("a response has an id")
}

