//! The container port: the sandboxes agent sessions run inside.

use std::future::Future;

use agent_runtime_protocol::domain::ports::Transport;
use agent_runtime_protocol::domain::schema::v0::{ToRuntimeMessage, ToServerMessage};
use agent_session::domain::model::AgentSessionId;

use crate::domain::error::Result;

/// Identifies one sandbox at its provider.
///
/// Not an [`AgentSessionId`]: a sandbox outlives and precedes the ACP session
/// it hosts, and providers mint these themselves. Keeping them distinct is what
/// stops a session id reaching an API that wants a sandbox id.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct ContainerId(String);

impl ContainerId {
    /// Name a sandbox.
    #[must_use]
    pub fn new(id: impl Into<String>) -> Self {
        Self(id.into())
    }

    /// Borrow the id's string form.
    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl std::fmt::Display for ContainerId {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        self.0.fmt(formatter)
    }
}

/// A live connection to the sandbox hosting one agent.
///
/// The sandbox speaks the `agent-runtime.v0` envelope: its hosted agent's raw
/// ACP frames wrapped as [`ToServerMessage::Acp`], plus lifecycle events the
/// agent itself knows nothing about.
pub trait Container: Transport<ToRuntimeMessage, ToServerMessage> + Send + Sync + 'static {
    /// Which sandbox this is, for reattaching to it later.
    fn container_id(&self) -> &ContainerId;
}

/// Provisions the sandboxes sessions run in.
///
/// `spawn` and `resume` are separate because a session's sandbox outlives any
/// one connection to it: a stopped or archived sandbox still holds the
/// workspace, so reattaching preserves the agent's working state where booting
/// a fresh one would discard it.
pub trait ContainerManager: Send + Sync + 'static {
    /// The container connection this manager hands out.
    type Container: Container;

    /// Boot a new sandbox for a session that has never had one.
    fn spawn(&self, session: AgentSessionId)
    -> impl Future<Output = Result<Self::Container>> + Send;

    /// Reattach to the sandbox a session already has, starting it if stopped.
    fn resume(
        &self,
        session: AgentSessionId,
    ) -> impl Future<Output = Result<Self::Container>> + Send;
}

