use std::collections::HashMap;
use std::sync::{Arc, Mutex};

use agent_session::domain::model::AgentSessionId;

use crate::domain::containers::{ContainerId, ContainerManager};
use crate::domain::error::{HarnessError, Result};
use crate::testing::helpers::container::ContainerMock;

/// Hands out [`ContainerMock`]s and remembers them.
///
/// Remembering is the point: `resume` returns the *same* container `spawn`
/// created, so a test can assert that reattaching preserves the sandbox's state
/// rather than silently starting a fresh one - which is what a real provider
/// does with a stopped sandbox, and what the Daytona adapter must do.
///
/// Cloning shares one provisioner, so a test can keep a handle after moving it
/// into a registry.
#[derive(Clone, Default)]
pub struct MockContainerManager {
    containers: Arc<Mutex<HashMap<AgentSessionId, ContainerMock>>>,
}

impl MockContainerManager {
    /// Create a provisioner that has spawned nothing.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// The container this session was given, so a test can drive it.
    #[must_use]
    pub fn container(&self, session: AgentSessionId) -> Option<ContainerMock> {
        self.lock().get(&session).cloned()
    }

    /// How many sandboxes have been booted.
    #[must_use]
    pub fn spawned(&self) -> usize {
        self.lock().len()
    }

    fn lock(&self) -> std::sync::MutexGuard<'_, HashMap<AgentSessionId, ContainerMock>> {
        self.containers
            .lock()
            .expect("container manager mock lock should not be poisoned")
    }
}

impl ContainerManager for MockContainerManager {
    type Container = ContainerMock;

    async fn spawn(&self, session: AgentSessionId) -> Result<ContainerMock> {
        let container = ContainerMock::new(ContainerId::new(format!("sandbox-{session}")));
        self.lock().insert(session, container.clone());
        Ok(container)
    }

    async fn resume(&self, session: AgentSessionId) -> Result<ContainerMock> {
        self.container(session).ok_or_else(|| {
            HarnessError::Container(format!("no sandbox was ever spawned for {session}"))
        })
    }
}

