use std::sync::{Arc, Mutex};

use agent_client_protocol::schema::v1::{ClientNotification, ClientRequest, RequestId};
use agent_client_protocol::{
    Error as AcpError, JsonRpcNotification, JsonRpcResponse, RawJsonRpcMessage,
