use agent_client_protocol::RawJsonRpcMessage;
use agent_client_protocol::schema::v1::{ClientRequest, NewSessionResponse, RequestId};
use agent_runtime_protocol::domain::ports::Transport;
use agent_runtime_protocol::domain::schema::v0::{
    AcpMessage, SystemEvent, ToRuntimeMessage, ToServerMessage,
};
use agent_session::domain::model::AgentSessionId;
use serde_json::json;

use super::*;
use crate::domain::containers::{Container, ContainerManager};
use crate::testing::helpers::container_manager::MockContainerManager;

/// A `session/prompt` request addressed to an ACP session.
fn prompt(id: RequestId) -> ToRuntimeMessage {
    ToRuntimeMessage::Acp(AcpMessage(
        RawJsonRpcMessage::request(
            "session/prompt".to_owned(),
            json!({
                "sessionId": "acp-abc",
                "prompt": [{ "type": "text", "text": "hello" }],
            }),
            id,
        )
        .unwrap(),
    ))
}

#[tokio::test]
async fn managed_session_speaks_to_its_container() {
    let session_id = AgentSessionId::TEST_A;
    let containers = MockContainerManager::new();
    let container = containers.spawn(session_id).await.unwrap();
    let agent = container.agent();
    container.sends_ready();

    let mut manager = AgentSessionManagerImpl::new({
        let container = container.clone();
        move |id: &AgentSessionId| AgentSessionImpl::new(*id, container.clone())
    });
    let session = manager.create_session(&session_id);

    session.send(prompt(RequestId::Number(1))).await.unwrap();

    assert!(matches!(
        agent.received_requests().as_slice(),
        [ClientRequest::PromptRequest(_)]
    ));
    assert!(matches!(
        session.receive().await.unwrap(),
        Some(ToServerMessage::Event {
            event: SystemEvent::AcpReady
        })
    ));

    agent.sends_reply(RequestId::Number(1), NewSessionResponse::new("acp-abc"));
    assert!(matches!(
        session.receive().await.unwrap(),
        Some(ToServerMessage::Acp(_))
    ));
    assert_eq!(manager.from_id(&session_id).unwrap().id(), &session_id);
}

/// Reattaching must hand back the sandbox that already exists, not a new one:
/// a fresh sandbox would discard the agent's workspace.
#[tokio::test]
async fn resuming_reuses_the_sandbox_the_session_already_has() {
    let session_id = AgentSessionId::TEST_A;
    let containers = MockContainerManager::new();

    let spawned = containers.spawn(session_id).await.unwrap();
    let resumed = containers.resume(session_id).await.unwrap();

    assert_eq!(resumed.container_id(), spawned.container_id());
    assert_eq!(containers.spawned(), 1);

    // Same container, so the agent inside it is the same one: a frame sent to
    // the spawned handle is visible through the resumed one.
    Transport::send(&spawned, prompt(RequestId::Number(1)))
        .await
        .unwrap();
    assert_eq!(resumed.agent().received_frames().len(), 1);
}

#[tokio::test]
async fn resuming_a_session_that_never_had_a_sandbox_fails() {
    let containers = MockContainerManager::new();
    assert!(containers.resume(AgentSessionId::TEST_B).await.is_err());
}

