//! The agent-link port.

use agent_runtime_protocol::domain::ports::Transport;
use agent_runtime_protocol::domain::schema::v0::{ToRuntimeMessage, ToServerMessage};

/// A live link carrying one agent's `agent-runtime.v0` traffic.
///
/// A session buffers, handshakes and flushes over this and nothing else - it
/// never learns who owns the process at the far end or how the link was
/// established. That is what lets one set of buffering rules serve both a
/// sandbox we booted ([`crate::domain::containers::Container`]) and, later, a
/// container someone else spawned on a webhook and dialed into a WebSocket
/// server of ours.
