        &self.id
    }

    pub async fn send(&self, message: ToRuntimeMessage) -> Result<(), TransportError> {
        self.connector.send(message).await
    }

    pub async fn receive(&self) -> Result<Option<ToServerMessage>, TransportError> {
        self.connector.recv().await
    }
}

