use agent_client_protocol::schema::v1::{
    InitializeRequest, NewSessionRequest, NewSessionResponse, ProtocolVersion, RequestId,
};
use agent_client_protocol::{JsonRpcMessage, RawJsonRpcMessage};
use agent_runtime_protocol::domain::acp_id::AcpId;
use agent_runtime_protocol::domain::action::AgentAction;
use agent_runtime_protocol::domain::schema::v0::{
    AcpMessage, SystemEvent, ToRuntimeMessage, ToServerMessage,
};
use agent_session::domain::model::{AgentSessionId, AgentSessionLog, Message};
use agent_session::domain::ports::AgentSessionLogRepo;
use serde::Serialize;

use crate::domain::connector::AgentConnector;
use crate::domain::error::{HarnessError, Result};

/// Working directory every ACP session is created in, matching where the
/// container image clones the repo.
const WORKSPACE: &str = "/workspace";

/// Reserved id for our own `initialize`. Namespaced, so a caller's request id
/// can never collide with it.
pub const INITIALIZE_ID: &str = "agent_harness:initialize";
/// Reserved id for our own `session/new`.
pub const NEW_SESSION_ID: &str = "agent_harness:session/new";

enum SessionState {
    /// The sandbox is still booting. Nothing may go on the wire.
    Booting { pending: Vec<AgentAction> },
    /// `AcpReady` seen and the handshake is in flight. Still buffering: an
    /// action needs the [`AcpId`] `session/new` has not returned yet.
    Handshaking { pending: Vec<AgentAction> },
    Live { acp: AcpId },
    Dead,
}

/// A session's state without its payload, so callers can observe transitions.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SessionStatus {
    Booting,
    Handshaking,
    Live,
    Dead,
}

/// One agent session and the link it speaks over.
pub struct AgentSession<Connector, Logs> {
    id: AgentSessionId,
    connector: Connector,
    logs: Logs,
    state: SessionState,
    next_prompt: u64,
}

impl<Connector, Logs> AgentSession<Connector, Logs>
where
    Connector: AgentConnector,
    Logs: AgentSessionLogRepo,
{
    pub fn new(id: AgentSessionId, connector: Connector, logs: Logs) -> Self {
        Self {
            id,
            connector,
            logs,
            state: SessionState::Booting {
                pending: Vec::new(),
            },
            next_prompt: 0,
        }
    }

    pub fn id(&self) -> &AgentSessionId {
        &self.id
    }

    pub fn status(&self) -> SessionStatus {
        match &self.state {
            SessionState::Booting { .. } => SessionStatus::Booting,
            SessionState::Handshaking { .. } => SessionStatus::Handshaking,
            SessionState::Live { .. } => SessionStatus::Live,
            SessionState::Dead => SessionStatus::Dead,
        }
    }

    pub fn acp_id(&self) -> Option<&AcpId> {
        match &self.state {
            SessionState::Live { acp } => Some(acp),
            _ => None,
        }
    }

    /// Queue an action, or send it now if the handshake has finished.
    pub async fn send_message(&mut self, action: AgentAction) -> Result<()> {
        match &mut self.state {
            SessionState::Booting { pending } | SessionState::Handshaking { pending } => {
                pending.push(action);
                Ok(())
            }
            SessionState::Live { acp } => {
                let message = action.to_runtime(&acp.clone(), self.next_prompt_id())?;
                self.send_now(message).await
            }
            SessionState::Dead => Err(HarnessError::Disconnected(self.id)),
        }
    }

    /// Handle one inbound message. `false` once the connector's stream ends.
    pub async fn step(&mut self) -> Result<bool> {
        let Some(message) = self.connector.recv().await? else {
            self.state = SessionState::Dead;
            return Ok(false);
        };
        self.log(Message::ToServer(message.clone())).await?;

        match message {
            ToServerMessage::Event {
                event: SystemEvent::AcpReady,
            } => self.begin_handshake().await?,
            ToServerMessage::Acp(AcpMessage(frame)) => self.on_frame(frame).await?,
            _ => {}
        }
        Ok(true)
    }

    /// `step` until the connector's stream ends.
    pub async fn pump(&mut self) -> Result<()> {
        while self.step().await? {}
        Ok(())
    }

    /// Ready means handshakeable, not sendable: `initialize` and `session/new`
    /// go out together, and queued actions keep waiting for the ACP session id.
    async fn begin_handshake(&mut self) -> Result<()> {
        let SessionState::Booting { pending } = &mut self.state else {
            return Ok(());
        };
        let pending = std::mem::take(pending);

        self.send_now(acp_request(
            &InitializeRequest::new(ProtocolVersion::V1),
            RequestId::Str(INITIALIZE_ID.to_owned()),
        )?)
        .await?;
        self.send_now(acp_request(
            &NewSessionRequest::new(WORKSPACE),
            RequestId::Str(NEW_SESSION_ID.to_owned()),
        )?)
        .await?;

        self.state = SessionState::Handshaking { pending };
        Ok(())
    }

    async fn on_frame(&mut self, frame: RawJsonRpcMessage) -> Result<()> {
        let Some(RequestId::Str(answered)) = frame.response_id() else {
            return Ok(());
        };
        if answered != NEW_SESSION_ID {
            return Ok(());
        }

        let RawJsonRpcMessage::Response(response) = &frame else {
            return Ok(());
        };
        let acp = new_session_id(response)?;
        self.go_live(acp).await
    }

    /// Record the ACP session id, then drain everything queued before it existed.
    async fn go_live(&mut self, acp: AcpId) -> Result<()> {
        let SessionState::Handshaking { pending } = &mut self.state else {
            return Ok(());
        };
        let pending = std::mem::take(pending);
        self.state = SessionState::Live { acp: acp.clone() };

        for action in pending {
            let message = action.to_runtime(&acp, self.next_prompt_id())?;
            self.send_now(message).await?;
        }
        Ok(())
    }

    async fn send_now(&self, message: ToRuntimeMessage) -> Result<()> {
        self.log(Message::ToRuntime(message.clone())).await?;
        self.connector.send(message).await?;
        Ok(())
    }

    async fn log(&self, content: Message) -> Result<()> {
        self.logs
            .create(AgentSessionLog {
                agent_session_id: self.id,
                user_id: None,
                content,
            })
            .await?;
        Ok(())
    }

    fn next_prompt_id(&mut self) -> RequestId {
        let id = RequestId::Str(format!("agent_harness:prompt:{}", self.next_prompt));
        self.next_prompt += 1;
        id
    }
}

/// Wrap a typed ACP request as an outbound message, taking its method name from
/// the request's own type.
fn acp_request(
    payload: &(impl JsonRpcMessage + Serialize),
    id: RequestId,
) -> Result<ToRuntimeMessage> {
    let params = serde_json::to_value(payload)
        .map_err(|error| HarnessError::Container(error.to_string()))?;
    let frame = RawJsonRpcMessage::request(payload.method().to_owned(), params, id)
        .map_err(|error| HarnessError::Container(error.to_string()))?;
    Ok(ToRuntimeMessage::Acp(AcpMessage(frame)))
}

/// Read the ACP session id out of a `session/new` response.
fn new_session_id(
    response: &agent_client_protocol::schema::v1::Response<serde_json::Value, agent_client_protocol::Error>,
) -> Result<AcpId> {
    use agent_client_protocol::schema::v1::Response;
    let Response::Result { result, .. } = response else {
        return Err(HarnessError::Container(
            "the agent refused session/new".to_owned(),
        ));
    };
    let parsed: NewSessionResponse = serde_json::from_value(result.clone())
        .map_err(|error| HarnessError::Container(error.to_string()))?;
    Ok(parsed.session_id.into())
}

