use agent_session::domain::model::{AgentSessionId, NewAgentSession};
use agent_session::domain::ports::{AgentSessionLogRepo, AgentSessionRepo};

use crate::domain::agent_sessions::session::AgentSession;
use crate::domain::containers::ContainerManager;
use crate::domain::error::Result;

/// Creates agent sessions: mints the row, provisions the sandbox, wires them.
///
/// Hands over ownership rather than keeping a table - each session drives its
/// own state machine, so nothing here holds one.
pub struct AgentSessionManager<Containers, Sessions, Logs> {
    containers: Containers,
    sessions: Sessions,
    logs: Logs,
}

impl<Containers, Sessions, Logs> AgentSessionManager<Containers, Sessions, Logs>
where
    Containers: ContainerManager,
    Sessions: AgentSessionRepo,
    Logs: AgentSessionLogRepo + Clone,
{
    pub fn new(containers: Containers, sessions: Sessions, logs: Logs) -> Self {
        Self {
            containers,
            sessions,
            logs,
        }
    }

    /// Open a session that has never run: mint its row, boot it a sandbox.
    pub async fn open(
        &self,
        new: NewAgentSession,
    ) -> Result<AgentSession<Containers::Container, Logs>> {
        let record = self.sessions.create(new).await?;
        let container = self.containers.spawn(record.id).await?;
        Ok(AgentSession::new(record.id, container, self.logs.clone()))
    }

    /// Reattach to a session whose row already exists.
    ///
    /// The sandbox survives, its ACP session does not: `session/load` is
    /// unimplemented, so the handshake mints a fresh one and the agent starts
    /// without the earlier conversation.
    pub async fn resume(
        &self,
        id: AgentSessionId,
    ) -> Result<AgentSession<Containers::Container, Logs>> {
        let record = self.sessions.get(id).await?;
        let container = self.containers.resume(record.id).await?;
        Ok(AgentSession::new(record.id, container, self.logs.clone()))
    }
}

